const email = $json;
const textOf = (value) => typeof value === 'string' ? value : (value?.text || '');
const sender = typeof email.from === 'string' ? email.from : (email.from?.value?.[0]?.address || email.from?.text || 'Sin remitente');
const subject = textOf(email.subject).trim() || '(Sin asunto)';
const plain = textOf(email.textPlain) || textOf(email.text);
const html = textOf(email.textHtml) || textOf(email.html);
const body = (plain || html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')).trim();
if (!body && !Object.keys($input.item.binary || {}).length) throw new Error('Correo sin texto ni adjuntos: revisar manualmente esta ejecución.');
const headers = email.headers || email.metadata || {};
const messageId = String(email.messageId || headers['message-id'] || email.attributes?.uid || 'sin-id');
return { binary: $input.item.binary || {}, json: { remitente: String(sender), asunto: subject.slice(0,255), cuerpo: (body || 'Correo sin texto; revisar los adjuntos.').slice(0,16000), texto_recortado: body.length > 16000, fecha: String(email.date || new Date().toISOString()), message_id: messageId, demo: email.demo === true } };

let result = $json.output;
if (typeof result === 'string') { try { result = JSON.parse(result); } catch { throw new Error('La IA no devolvió JSON válido. No se creó un ticket.'); } }
if (!result || typeof result !== 'object') throw new Error('Falta la salida estructurada de IA.');
const categories = ['aplicaciones','infraestructura','accesos','otros'];
const priorities = { baja:1, normal:2, alta:3, urgente:4 };
for (const key of ['resumen','descripcion']) if (typeof result[key] !== 'string' || !result[key].trim()) throw new Error('Campo IA inválido: '+key);
if (!categories.includes(result.categoria) || !Object.hasOwn(priorities,result.prioridad)) throw new Error('Categoría o prioridad fuera del catálogo.');
if (!Array.isArray(result.datos_faltantes) || !result.datos_faltantes.every(v=>typeof v==='string') || typeof result.requiere_revision !== 'boolean') throw new Error('Salida IA incompleta.');
const email = $('Normalizar correo').item.json;
const lines = [
 'Solicitud recibida por correo',
 'Remitente: '+email.remitente,
 'Asunto original: '+email.asunto,
 'Fecha: '+email.fecha,
 'Message-ID: '+email.message_id,
 '', 'ANÁLISIS DE IA', result.descripcion.slice(0,6000),
 'Categoría sugerida: '+result.categoria,
 'Prioridad sugerida: '+result.prioridad,
 'Requiere revisión: '+(result.requiere_revision ? 'Sí' : 'No'),
 'Datos faltantes: '+(result.datos_faltantes.slice(0,20).map(v=>v.slice(0,300)).join('; ') || 'Ninguno identificado'),
 '', 'TEXTO DEL CORREO'+(email.texto_recortado ? ' (recortado a 16000 caracteres)' : ''), email.cuerpo
];
return { json: { issue: { project_id:1, tracker_id:3, subject: ((email.demo ? '[DEMO] ' : '') + (result.requiere_revision ? '[REVISAR] ' : '') + result.resumen.trim()).slice(0,255), description:lines.join('\n'), priority_id: result.requiere_revision ? 2 : priorities[result.prioridad] } } };

const original = $input.item;
const supported = new Set(['image/png', 'image/jpeg', 'image/webp', 'application/pdf']);
const maxFile = 4 * 1024 * 1024;
const maxTotal = 8 * 1024 * 1024;
const maxFiles = 4;
const selected = {};
const inventory = [];
let total = 0;
for (const [key, file] of Object.entries(original.binary || {})) {
  const mime = String(file.mimeType || 'application/octet-stream').toLowerCase();
  const entry = { archivo: file.fileName || key, tipo: mime, para_ia: false, motivo: 'Formato no seleccionado para IA; se adjunta a Redmine.' };
  if (supported.has(mime)) {
    try {
      const buffer = await this.helpers.getBinaryDataBuffer($itemIndex, key);
      if (buffer.length <= maxFile && total + buffer.length <= maxTotal && Object.keys(selected).length < maxFiles) {
        selected[key] = file;
        total += buffer.length;
        entry.para_ia = true;
        entry.motivo = 'Seleccionado para análisis visual/documental.';
      } else {
        entry.motivo = 'Supera los límites de análisis IA; se adjunta a Redmine.';
      }
    } catch {
      entry.motivo = 'No se pudo preparar para IA; se intentará adjuntar a Redmine.';
    }
  }
  inventory.push(entry);
}
return { json: { ...original.json, adjuntos: inventory }, binary: selected };

const email = $('Normalizar correo').item.json;
return { json: {
  analisis_ia_fallido: true,
  output: {
    resumen: email.asunto || 'Solicitud con adjuntos para revisar',
    descripcion: 'No fue posible completar el análisis automático. Revisar el correo y los archivos adjuntos originales. No se afirma haber interpretado su contenido.',
    categoria: 'otros',
    prioridad: 'normal',
    requiere_revision: true,
    datos_faltantes: ['Revisión humana del correo y sus adjuntos; consultar el error de IA en la ejecución de n8n.'],
  },
} };

// Los originales se recuperan antes de la selección para IA, sin perder archivos.
const original = $('Normalizar correo').item;
const selection = $('Seleccionar adjuntos para IA').item.json;
const issue = { ...$json.issue };
const inventory = selection.adjuntos || [];
if (inventory.length) {
  const details = inventory.map(a => '- ' + a.archivo + ' [' + a.tipo + ']: ' + a.motivo).join('\n');
  issue.description += '\n\nARCHIVOS DEL CORREO\n' + details +
    '\nLa selección para IA no garantiza lectura: revisar el análisis o aviso de fallo anterior. Todos los archivos se cargarán en Redmine.';
}
return { json: { issue }, binary: original.binary || {} };

const output = [];
for (const [group, item] of $input.all().entries()) {
  const files = Object.entries(item.binary || {});
  for (const [key, file] of files) {
    const name = String(file.fileName || key).replace(/[\\/\x00-\x1f]/g, '_').slice(0, 200) || 'adjunto';
    output.push({
      json: { group, expected: files.length, issue: item.json.issue, filename: name,
        content_type: file.mimeType || 'application/octet-stream' },
      binary: { data: file },
      pairedItem: { item: group },
    });
  }
}
return output;

const groups = new Map();
for (const [index, item] of $input.all().entries()) {
  const origin = $('Separar adjuntos').itemMatching(index).json;
  const token = item.json.upload?.token;
  if (typeof token !== 'string' || !token) throw new Error('Redmine no devolvió el token para ' + origin.filename);
  if (!groups.has(origin.group)) groups.set(origin.group, { issue: { ...origin.issue, uploads: [] }, expected: origin.expected, pairedItem: [] });
  const group = groups.get(origin.group);
  group.issue.uploads.push({ token, filename: origin.filename, content_type: origin.content_type });
  group.pairedItem.push({ item: index });
}
return Array.from(groups.values(), group => {
  if (group.issue.uploads.length !== group.expected) throw new Error('Faltan adjuntos: se detiene la creación del ticket.');
  return { json: { issue: group.issue }, pairedItem: group.pairedItem };
});
